import{z as m,x as d,o as n,c as A,q as l,j as i,D as e,d as r,s,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Landmark Attention 原文","description":"","frontmatter":{"title":"Landmark Attention 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/landmark-paper.md","filePath":"llm/landmark-paper.md","lastUpdated":1791063341000}'),p={name:"llm/landmark-paper.md"};function B(h,a,k,f,c,u){const o=d("Mermaid");return n(),A("div",null,[a[2]||(a[2]=l('<h1 id="landmark-attention-原文" tabindex="-1">Landmark Attention 原文 <a class="header-anchor" href="#landmark-attention-原文" aria-label="Permalink to &quot;Landmark Attention 原文&quot;">​</a></h1><div class="epigraph"><p>不必让每个查询扫完整段历史；先问每一块的地标，再只对选中的块做随机访问，上下文长度就可以从二次扫描里解开。</p><footer>—— Mohtashami &amp; Jaggi，Landmark Attention: Random-Access Infinite Context Length for Transformers，2023</footer></div><p>EPFL 的 Amirkeivan Mohtashami 与 Martin Jaggi 的 Landmark Attention 把长上下文写成块级目录问题：每块插入一个地标 token，查询先对地标做一次粗检索，再只把命中块的原始键值载入做细注意力。远块不必按时间顺序扫过，目录分数高就可以直接展开——这就是标题里的 random-access。可见集变成「全部地标 + 少数块原文」，与序列长度解耦。本篇按 2023 年原文的训练图与两段 softmax 写；KV 预算的其它压法见 <a href="/llm/kv-as-long-context">KV 压缩作为长上下文手段</a>，概念速览见 <a href="/llm/landmark-attention">Landmark Attention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全注意力把过去每一个键放进可见集，长度一涨，二次代价与 KV 体积一起涨。滑窗把远键整段剪掉，针测失败。压缩记忆把远历史揉进固定状态，细节对不准。Transformer-XL 的段缓存仍是邻段前缀，不是任意远的随机访问。需要一种训练得出来的块级目录：目录项很少，每一项都能把查询带回那一块的原始 token。</p><p><span class="marginnote">术语翻译：「可见集」就是某一步注意力被允许看哪些键的清单。满注意力的清单是全部过去键；滑窗的清单只有最近一段；Landmark 的清单是「全部地标 + 命中块的原文」。改可见集就是改这张清单——它决定了模型每一步实际能引用哪些信息。</span></p><p>地标机制要同时回答：块内信息由谁代表；查询如何用代表做随机访问；训练时的可见集如何与推理时「先地标、后局部」对齐。做不到对齐，上线一改图就掉点；代表若是不可学习的均值，目录对所有查询相同，精确拷贝仍然失败。</p><h3 id="随机访问对时间顺序的拒绝" tabindex="-1">随机访问对时间顺序的拒绝 <a class="header-anchor" href="#随机访问对时间顺序的拒绝" aria-label="Permalink to &quot;随机访问对时间顺序的拒绝&quot;">​</a></h3><p>滑窗与 XL 缓存都假设「有用的远信息会沿时间渗过来」。小说里的伏笔、代码里的函数定义、定理证明里的引理，往往是内容寻址而不是时间近邻。Landmark 的问题设定因此是信息检索式的：先搜哪一块，再读块内文字，中间那些块可以不进细算。</p><p><span class="marginnote">地标是序列里的真实 token，不是块均值。均值对所有查询相同；地标的键随查询进入注意力，不同问题会点亮不同块。这是它和不可学习压缩记忆的差别。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="按块插入地标" tabindex="-1">按块插入地标 <a class="header-anchor" href="#按块插入地标" aria-label="Permalink to &quot;按块插入地标&quot;">​</a></h3><p>输入按固定块长 \\(\\ell\\) 切开，每块末尾插入一个地标。地标参与同一套注意力与前馈，占一个真实位置。训练时，块内普通 token 主要看见本块邻居；地标看见本块全部 token，被梯度逼成该块的可寻址代表。后续位置若不能直接扫过往全部键，就只能先碰到这些地标——目录是训出来的，不是外挂检索器。</p><h3 id="先对地标、再对局部" tabindex="-1">先对地标、再对局部 <a class="header-anchor" href="#先对地标、再对局部" aria-label="Permalink to &quot;先对地标、再对局部&quot;">​</a></h3><p>查询 \\(q_t\\) 先对已有地标键 \\(\\{k^{(L)}_b\\}\\) 打分。分高的块命中，再载入那些块的原始 \\(K,V\\) 做第二次局部 softmax。未命中的块既不进细算，也不必留在高速缓存。可见集与 \\(n\\) 解耦，只与块数（粗路）和选中块数 × \\(\\ell\\)（细路）有关：</p> \\[b^\\star=\\mathrm{top}\\text{-}k\\left(\\frac{q_t^\\top k^{(L)}_b}{\\sqrt{d}}\\right),\\qquad y_t=\\mathrm{softmax}\\!\\left(\\frac{q_t K_{b^\\star}^\\top}{\\sqrt{d}}\\right)V_{b^\\star}. \\]<p>也可以用地标分数做门控：超过阈值才展开。训练需要让地标键真能代理块内注意力质量，否则粗路点中的块细路用不上。</p><h3 id="训练图必须已经分层" tabindex="-1">训练图必须已经分层 <a class="header-anchor" href="#训练图必须已经分层" aria-label="Permalink to &quot;训练图必须已经分层&quot;">​</a></h3><p>若训练仍用满注意力、只在推理改成地标检索，分布会裂开。做法是让训练期可见集已经是：当前块局部边 + 过去块的地标边，必要时再对若干块做可微的软展开，使「凭地标跳进原文」成为网络的一部分。地标自己对块内做满注意力，梯度从后续查询经地标流回块内 token。与 Longformer 全局点不同：全局点是任务指定的少数中枢，地标是按块均匀铺开的目录。与 Memorizing Transformers 的 kNN 不同：那里检索的是过去层的 \\((k,v)\\) 向量，地标是序列里显式的 token 接口。</p>',19)),(n(),i(E,null,{default:e(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E5%88%87%E5%9D%97%22%5D%20--%3E%20B%5B%22%E6%AF%8F%E5%9D%97%E6%8F%92%E5%85%A5%E5%9C%B0%E6%A0%87%20token%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9F%A5%E8%AF%A2%E5%85%88%E5%AF%B9%E5%9C%B0%E6%A0%87%E6%89%93%E5%88%86%22%5D%0A%20%20C%20--%3E%20D%5B%22top-k%20%E6%88%96%E9%97%A8%E6%8E%A7%E9%80%89%E5%9D%97%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%9D%97%E5%86%85%E5%8E%9F%E5%A7%8B%20token%20%E7%BB%86%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"两段 softmax 把质量分配拆成「哪一段可能有答案」与「段内哪一个键」。只要 \\(\\ell\\) 落在一层局部注意力的舒适跨度内，块内尖峰能力仍在，拷贝与针测仍可能——失败出在粗路漏块。\\(\\ell\\) 太长，一个地标代表太多互不相关的句子，目录变钝，细路二次项也回来；太短，地标数接近 \\(n\\)，粗路自己又变成二次。",-1)),a[5]||(a[5]=t("p",null,"两段 softmax 不是一次满注意力的恒等改写。粗路用一个键代替整块，等价于对块内键做了内容相关的池化。漏块不可逆：细路看不见的 token 权重精确为零。这与 Beacon 的区别是：Beacon 的细路默认也不看早块原文，只看摘要；Landmark 在命中之后看的是原文，因此随机访问一旦点对，细节可以精确。未命中则比 Beacon 更惨——连糊摘要都没有。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"数字实例：\\(n=131072\\)（128K）、\\(\\ell=128\\) 时，粗路目录只有 \\(131072/128=1024\\) 个地标；命中 8 块则细路对约 \\(8\\times 128=1024\\) 个原文键打分。满注意力要对 \\(131072^2\\approx 1.7\\times 10^{10}\\) 个格子打分——两段式把每步的打分规模从百亿量级压到千级，代价是漏块风险。")],-1)),(n(),i(E,null,{default:e(()=>[s(o,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E9%9C%80%E8%A6%81%E8%BF%9C%E5%A4%84%E7%BB%86%E8%8A%82%22%5D%20--%3E%20C%5B%22%E7%B2%97%E8%B7%AF%E5%AF%B9%E5%9C%B0%E6%A0%87%E6%89%93%E5%88%86%22%5D%0A%20%20C%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E7%AD%94%E6%A1%88%E6%89%80%E5%9C%A8%E5%9D%97%22%5D%0A%20%20C%20--%3E%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%5D%0A%20%20HIT%20--%3E%20O%5B%22%E7%BB%86%E8%B7%AF%E8%AF%BB%E5%9D%97%E5%86%85%E5%8E%9F%E6%96%87%2C%E7%BB%86%E8%8A%82%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20MISS%20--%3E%20Z%5B%22%E8%AF%A5%E5%9D%97%E6%9D%83%E9%87%8D%E7%B2%BE%E7%A1%AE%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20Z%20--%3E%20L%5B%22%E6%8D%9F%E5%A4%B1%E7%9C%8B%E4%BC%BC%E6%AD%A3%E5%B8%B8%2C%E9%92%88%E6%B5%8B%E5%8D%B4%E5%B4%A9%E6%BA%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">应单独报块召回，而不是只报最终损失。语言建模可以靠局部流畅撑住，同时粗路系统性漏掉定义块。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>离散选块会漏。top-\\(k\\) 太狠，答案所在块进不了细路，针测突然崩溃而不是平滑掉点。太松，又走回近似满注意力。地标占上下文一个位置，块很多时目录扫描也有成本，极端长度要对地标再分级。不要把 Landmark 理解成「推理时对 KV 做聚类」：代表是训练出来的 token，对已训好的满注意力模型事后插地标、不微调，目录没有语义。也不要和 MLA 混名：MLA 压每个 token 的秩，地标压序列维的块数。</p><p><span class="marginnote">常见误区：初学者容易以为「找一个训好的模型，推理时给 KV 聚个类、插个地标就能扩上下文」。实际上地标的价值在于训练时后续位置就只能先看见它——模型的其余权重已经围绕这个约束重新分配过了。绕过训练直接改推理图，等于给一张按老地图画的导航装上新路标，司机不认。</span></p><p>部署上，未选中块的 KV 可以下放到主机内存或丢掉，这才是「无限上下文」的工程含义——细算只打在命中块上，不是算力无限。取舍：需要任意位置的精确随机访问，地标是对口工具；只需要最近窗口加指令前缀，滑窗更便宜。</p><p><span class="marginnote">与 Activation Beacon 同时读时：一个训的是「压缩后仍可见的摘要 token」，一个训的是「可展开的目录 token」。产品若必须逐字引用，Landmark 的细路原文更合适；若只要章节大意且 \\(n\\) 极大，Beacon 的固定压缩率更可预测。</span></p><h3 id="原文之后的谱系" tabindex="-1">原文之后的谱系 <a class="header-anchor" href="#原文之后的谱系" aria-label="Permalink to &quot;原文之后的谱系&quot;">​</a></h3><p>Focused Transformer 用对比学习改善缓存里相关键的区分；NSA 把压缩支路写进融核。Landmark 2023 的主场仍是标准注意力上改掩码与两段检索，实现相对直接。读 2024 年检索式 KV 论文时，地标是「块代表可学习、检索可训练」这一支的早期完整形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Landmark Attention 原文把序列切块，每块一个可学习地标；查询先对地标、再对命中块原文。</li><li>随机访问：远块不必按时间扫过，目录命中即可展开。</li><li>训练可见集必须已分层；两段 softmax 会漏块，应报块召回。</li><li>压缩轴是序列块，不是头数或精度；与 MLA、H2O、kNN 记忆不是同一件事。</li><li>出处：Mohtashami &amp; Jaggi，<em>Landmark Attention: Random-Access Infinite Context Length for Transformers</em>，2023，arXiv:2305.16300。对照 Beltagy 等 Longformer（2020）、Wu 等 Memorizing Transformers（2022）、Zhang 等 Activation Beacon（2024）。</li></ul>',10))])}const L=m(p,[["render",B]]);export{b as __pageData,L as default};
